css:
/* ==== People Puzzle — Warm Retail / Consumer theme adapted for HR narrative ==== */
.motivation-sim-container {
    padding: 24px;
    background: linear-gradient(180deg, #fff7ed 0%, #fde7d2 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #3b2a1a;
}

.motivation-sim-container .motivation-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
    background: linear-gradient(135deg, #7c2d12, #c2410c);
    color: #fff7ed;
    border-radius: 18px;
    padding: 22px 28px;
    margin-bottom: 24px;
    box-shadow: 0 10px 28px rgba(124,45,18,0.25);
}

.motivation-sim-container .motivation-sim-brand {
    display: flex;
    align-items: center;
    gap: 14px;
}

.motivation-sim-container .motivation-sim-logo {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: #fff7ed;
    color: #7c2d12;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    letter-spacing: 0.05em;
}

.motivation-sim-container .motivation-sim-header h1 {
    margin: 0;
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: 0.01em;
}

.motivation-sim-container .motivation-sim-subtitle {
    font-size: 0.82rem;
    opacity: 0.9;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-top: 4px;
}

.motivation-sim-container .motivation-sim-period-pill {
    background: rgba(255,247,237,0.2);
    border: 1px solid rgba(255,247,237,0.35);
    padding: 8px 14px;
    border-radius: 999px;
    font-weight: 600;
    font-size: 0.95rem;
}

.motivation-sim-container .motivation-sim-briefing {
    background: #ffffff;
    border-radius: 16px;
    padding: 22px 26px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(76,29,13,0.08);
    border-left: 6px solid #ea580c;
}

.motivation-sim-container .motivation-sim-briefing-label {
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #9a3412;
    margin-bottom: 6px;
}

.motivation-sim-container .motivation-sim-briefing-title {
    margin: 0 0 10px 0;
    font-size: 1.3rem;
    color: #7c2d12;
}

.motivation-sim-container .motivation-sim-briefing-text {
    font-size: 1rem;
    line-height: 1.55;
    color: #3b2a1a;
}

.motivation-sim-container .motivation-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}

.motivation-sim-container .motivation-sim-kpi-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 18px;
    box-shadow: 0 4px 12px rgba(76,29,13,0.08);
    border-top: 5px solid #fb923c;
    transition: transform 0.2s ease;
}

.motivation-sim-container .motivation-sim-kpi-card:hover {
    transform: translateY(-3px);
}

.motivation-sim-container .motivation-sim-kpi-blue { border-top-color: #0284c7; }
.motivation-sim-container .motivation-sim-kpi-green { border-top-color: #16a34a; }
.motivation-sim-container .motivation-sim-kpi-amber { border-top-color: #d97706; }
.motivation-sim-container .motivation-sim-kpi-purple { border-top-color: #7c3aed; }

.motivation-sim-container .motivation-sim-kpi-label {
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #78350f;
    margin-bottom: 8px;
}

.motivation-sim-container .motivation-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #7c2d12;
    line-height: 1.1;
}

.motivation-sim-container .motivation-sim-team-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.motivation-sim-container .motivation-sim-employee-card {
    background: #ffffff;
    border-radius: 16px;
    padding: 18px;
    box-shadow: 0 4px 14px rgba(76,29,13,0.08);
    border: 1px solid #fde7d2;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.motivation-sim-container .motivation-sim-employee-head {
    display: flex;
    align-items: center;
    gap: 12px;
}

.motivation-sim-container .motivation-sim-avatar {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-weight: 700;
    font-size: 1.05rem;
    flex-shrink: 0;
}

.motivation-sim-container .motivation-sim-avatar-ravi { background: #0ea5e9; }
.motivation-sim-container .motivation-sim-avatar-eleni { background: #a855f7; }
.motivation-sim-container .motivation-sim-avatar-martin { background: #475569; }
.motivation-sim-container .motivation-sim-avatar-zara { background: #ec4899; }

.motivation-sim-container .motivation-sim-emp-info {
    flex: 1;
}

.motivation-sim-container .motivation-sim-emp-name {
    font-weight: 700;
    font-size: 1.05rem;
    color: #7c2d12;
}

.motivation-sim-container .motivation-sim-emp-role {
    font-size: 0.8rem;
    color: #9a3412;
}

.motivation-sim-container .motivation-sim-mood {
    font-size: 1.8rem;
    transition: transform 0.25s ease;
}

.motivation-sim-container .motivation-sim-bars {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.motivation-sim-container .motivation-sim-bar-row {
    display: grid;
    grid-template-columns: 110px 1fr 36px;
    align-items: center;
    gap: 10px;
    font-size: 0.78rem;
    color: #3b2a1a;
}

.motivation-sim-container .motivation-sim-bar {
    background: #fde7d2;
    height: 8px;
    border-radius: 999px;
    overflow: hidden;
}

.motivation-sim-container .motivation-sim-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #f97316, #16a34a);
    transition: width 0.5s ease;
}

.motivation-sim-container .motivation-sim-bubble {
    background: #fff7ed;
    border: 1px dashed #fdba74;
    border-radius: 12px;
    padding: 10px 12px;
    font-size: 0.88rem;
    color: #3b2a1a;
    position: relative;
    min-height: 42px;
}

.motivation-sim-container .motivation-sim-controls {
    background: #ffffff;
    border-radius: 18px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(76,29,13,0.08);
}

.motivation-sim-container .motivation-sim-controls h3 {
    margin: 0 0 14px 0;
    color: #7c2d12;
    font-size: 1.1rem;
    font-weight: 700;
}

.motivation-sim-container .motivation-sim-field {
    margin-bottom: 14px;
}

.motivation-sim-container .motivation-sim-field label {
    display: block;
    font-size: 0.82rem;
    font-weight: 600;
    color: #7c2d12;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.motivation-sim-container select,
.motivation-sim-container input[type="number"],
.motivation-sim-container input[type="text"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #fdba74;
    background: #fff7ed;
    color: #3b2a1a;
    border-radius: 10px;
    font-size: 0.95rem;
}

.motivation-sim-container select option {
    background: #ffffff;
    color: #3b2a1a;
}

.motivation-sim-container .motivation-sim-buttons {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-top: 8px;
}

.motivation-sim-container #nextPeriodBtn {
    background: linear-gradient(135deg, #c2410c, #7c2d12);
    border: none;
    color: #fff7ed;
    font-weight: 700;
    padding: 10px 22px;
    border-radius: 10px;
    letter-spacing: 0.02em;
}

.motivation-sim-container #nextPeriodBtn:hover {
    filter: brightness(1.08);
}

.motivation-sim-container #undoBtn {
    border: 1px solid #9a3412;
    color: #7c2d12;
    background: #fff7ed;
    border-radius: 10px;
}

.motivation-sim-container .motivation-sim-stamp {
    text-align: center;
    font-weight: 800;
    font-size: 1.1rem;
    letter-spacing: 0.25em;
    padding: 8px 0;
    margin-bottom: 18px;
    min-height: 1.8rem;
    color: #7c2d12;
    text-transform: uppercase;
    opacity: 0;
    transition: opacity 0.4s ease;
}

.motivation-sim-container .motivation-sim-stamp.motivation-sim-stamp-show {
    opacity: 1;
}

.motivation-sim-container .motivation-sim-history,
.motivation-sim-container .motivation-sim-chart {
    background: #ffffff;
    border-radius: 16px;
    padding: 20px 22px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(76,29,13,0.08);
}

.motivation-sim-container .motivation-sim-history h3,
.motivation-sim-container .motivation-sim-chart h3 {
    margin: 0 0 12px 0;
    color: #7c2d12;
    font-size: 1.05rem;
    font-weight: 700;
}

.motivation-sim-container .motivation-sim-chart canvas {
    width: 100%;
    max-height: 280px;
}

.motivation-sim-container table.table {
    margin-bottom: 0;
    font-size: 0.9rem;
}

.motivation-sim-container table.table th {
    color: #7c2d12;
    border-bottom: 2px solid #fdba74;
    background: #fff7ed;
}

.motivation-sim-container table.table td {
    color: #3b2a1a;
    vertical-align: middle;
}

@media (max-width: 768px) {
    .motivation-sim-container {
        padding: 14px;
    }
    .motivation-sim-container .motivation-sim-header h1 {
        font-size: 1.1rem;
    }
    .motivation-sim-container .motivation-sim-kpi-value {
        font-size: 1.5rem;
    }
    .motivation-sim-container .motivation-sim-bar-row {
        grid-template-columns: 90px 1fr 30px;
        font-size: 0.72rem;
    }
}

