            const state = window.mySimulation.state;
            const emps = state.domainState.employees;
            const finalEng = this.EMPLOYEES.map(k => emps[k].eng);
            const avgEng = this._avg(finalEng);
            const minEng = Math.min.apply(null, finalEng);
            const allAbove75 = finalEng.every(v => v >= 75);
            const allRetained = this.EMPLOYEES.every(k => emps[k].stay >= 40);
            const accuracy = Math.round(100 * state.domainState.theoryHits / Math.max(1, state.domainState.theoryAttempts));

            let stars = 0;
            let performance_key = 'perf_manager';
            if (allRetained) stars = 1;
            if (avgEng >= 70) { stars = 2; performance_key = 'perf_people'; }
            if (allAbove75 && accuracy >= 80) { stars = 3; performance_key = 'perf_talent'; }

            const insights = [];
            insights.push(window.mySimulation.t('insight_avg').replace('{v}', Math.round(avgEng)));
            insights.push(window.mySimulation.t('insight_min').replace('{v}', Math.round(minEng)));
            insights.push(window.mySimulation.t('insight_theory').replace('{v}', accuracy));
            if (!allRetained) insights.push(window.mySimulation.t('insight_lost'));
            if (allAbove75) insights.push(window.mySimulation.t('insight_all_high'));

            return {
                avg_engagement: avgEng,
                min_engagement: minEng,
                theory_accuracy: accuracy,
                stars: stars,
                performance: window.mySimulation.t(performance_key),
                insights: insights
            };
        }

        // platform score: the star verdict of getPerformanceSummary (0 to 3 stars, same rules) as bands of 25 points, average engagement places the score inside its band
        _platformScore(ds) {
            const eng = this.EMPLOYEES.map(k => ds.employees[k].eng);
            const avgEng = this._avg(eng);
            const allAbove75 = eng.every(v => v >= 75);
            const allRetained = this.EMPLOYEES.every(k => ds.employees[k].stay >= 40);
            const accuracy = Math.round(100 * ds.theoryHits / Math.max(1, ds.theoryAttempts));
            let stars = 0;
            if (allRetained) stars = 1;
            if (avgEng >= 70) stars = 2;
            if (allAbove75 && accuracy >= 80) stars = 3;
            const lo = [0, 0, 70, 75][stars];
            const hi = [100, 70, 100, 100][stars];
            const f = Math.max(0, Math.min(1, (avgEng - lo) / (hi - lo)));
            return Math.max(0, Math.min(100, Math.round(stars * 25 + f * (stars === 3 ? 25 : 24))));
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.avg_engagement != null && results.avg_engagement < 55) return window.mySimulation.t('hint_low_eng');
            if (results.theory_match === window.mySimulation.t('match_no')) return window.mySimulation.t('hint_wrong_theory');
            if (state.domainState.employees.martin.eng < 50) return window.mySimulation.t('hint_martin_safety');
            if (state.domainState.employees.eleni.eng < 55) return window.mySimulation.t('hint_eleni_bored');
            return null;
        }

