        _clamp(v) {
            if (v < 0) return 0;
            if (v > 100) return 100;
            return v;
        }

        _avg(arr) {
            if (!arr.length) return 0;
            return arr.reduce((s, x) => s + x, 0) / arr.length;
        }

        _actionLabelKey(round, actionValue) {
            const opt = round.options.find(o => o.value === actionValue);
            return opt ? opt.label_key : 'action_label';
        }

        _updateBriefing(state) {
            const period = state.currentPeriod || 1;
            const roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[roundIdx];
            const t = (k) => window.mySimulation.t(k);

            const titleEl = document.getElementById('roundTitle');
            const briefEl = document.getElementById('briefingText');
            if (titleEl) titleEl.textContent = t(round.title_key);
            if (briefEl) briefEl.innerHTML = t(round.desc_key);

            const actionSelect = document.getElementById('actionSelect');
            if (actionSelect) {
                actionSelect.innerHTML = '';
                round.options.forEach((opt) => {
                    const o = document.createElement('option');
                    o.value = opt.value;
                    o.textContent = t(opt.label_key);
                    actionSelect.appendChild(o);
                });
            }
        }

        _renderTeam(state) {
            const employees = state.domainState.employees;
            this.EMPLOYEES.forEach((key) => {
                const emp = employees[key];
                this._setBar('bar_eng_'  + key, 'val_eng_'  + key, emp.eng);
                this._setBar('bar_stay_' + key, 'val_stay_' + key, emp.stay);
                this._setBar('bar_prod_' + key, 'val_prod_' + key, emp.prod);
                this._setMood('mood_' + key, emp.eng);
            });
        }

        // KPI cards painted from domainState with the same formats as the setupUI bindings. The bindings read
        // results, which do not exist before Round 1 (or after undoing it), so without this the cards kept
        // the placeholder text of the view instead of the real opening averages.
        _paintKpis(state) {
            const ds = state && state.domainState;
            if (!ds || !ds.employees) return;
            const t = (k) => window.mySimulation.t(k);
            const avgOf = (f) => this._avg(this.EMPLOYEES.map(k => ds.employees[k][f]));
            const put = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
            const stay = avgOf('stay');
            put('avgEngagementDisplay', Math.round(avgOf('eng')) + '%');
            put('productivityDisplay', Math.round(avgOf('prod')) + '%');
            put('retentionDisplay', stay >= 75 ? t('risk_low') : (stay >= 55 ? t('risk_medium') : t('risk_high')));
            put('theoryDisplay', ds.theoryAttempts ? Math.round(100 * ds.theoryHits / Math.max(1, ds.theoryAttempts)) + '%' : '—');
        }

        _setBar(barId, valId, v) {
            const bar = document.getElementById(barId);
            const val = document.getElementById(valId);
            if (bar) bar.style.width = Math.round(v) + '%';
            if (val) val.textContent = Math.round(v);
        }

        _setMood(id, eng) {
            const el = document.getElementById(id);
            if (!el) return;
            if (eng >= 80) el.textContent = '😄';
            else if (eng >= 65) el.textContent = '🙂';
            else if (eng >= 50) el.textContent = '😐';
            else if (eng >= 35) el.textContent = '😕';
            else el.textContent = '😞';
        }

        _flashReasoningStamp(theoryValue) {
            const el = document.getElementById('reasoningStamp');
            if (!el) return;
            const label = window.mySimulation.t('theory_' + theoryValue) || theoryValue;
            el.textContent = label;
            el.classList.add('motivation-sim-stamp-show');
            setTimeout(function() {
                el.classList.remove('motivation-sim-stamp-show');
            }, 1600);
        }
